'use strict';

/**
 * Canonical policy rules for Maestro command safety enforcement.
 * Used by:
 *   - src/platforms/shared/policy-enforcer.js (the PreToolUse hook runner behind
 *     the Claude Code and Antigravity policy enforcers)
 *   - policies/maestro.toml (Qwen Code policy pack — generated by src/platforms/qwen/policy-pack.js)
 *
 * Rule shapes:
 *   { matchType: 'prefix' | 'regex' | 'word', pattern: string, reason: string }
 */

const DENY_RULES = Object.freeze([
  { matchType: 'prefix', pattern: 'rm -rf', reason: 'Recursive force delete' },
  { matchType: 'prefix', pattern: 'rm -fr', reason: 'Recursive force delete (flag reorder)' },
  { matchType: 'prefix', pattern: 'sudo rm -rf', reason: 'Privileged recursive force delete' },
  { matchType: 'prefix', pattern: 'sudo rm -fr', reason: 'Privileged recursive force delete (flag reorder)' },
  { matchType: 'prefix', pattern: 'git reset --hard', reason: 'Discards uncommitted changes' },
  { matchType: 'prefix', pattern: 'git checkout --', reason: 'Discards uncommitted file changes' },
  { matchType: 'prefix', pattern: 'git clean -fd', reason: 'Removes untracked files permanently' },
  { matchType: 'prefix', pattern: 'git clean -df', reason: 'Removes untracked files permanently (flag reorder)' },
  { matchType: 'prefix', pattern: 'git clean -xfd', reason: 'Removes untracked and ignored files permanently' },
  { matchType: 'prefix', pattern: 'git clean -xdf', reason: 'Removes untracked and ignored files permanently (flag reorder)' },
  // A heredoc operator: `<<` or `<<-`, optional blanks, then a delimiter word,
  // bare or quoted (`<<EOF`, `<< 'EOF'`, `<<-"EOF"`, `<<\EOF`). The leading
  // `(?:^|[^<])` skips here-strings (`<<<`); requiring a delimiter word skips
  // arithmetic shifts (`$((1<<4))`, `1 << 3`) and `<<=`. No lookbehind, so the
  // same pattern works as a policy-pack commandRegex.
  { matchType: 'regex', pattern: '(?:^|[^<])<<-?[ \\t]*[\'"\\\\]?[A-Za-z_]', reason: 'Heredoc corrupts structured content (YAML, Markdown, JSON) — use the file-writing tool instead' },
]);

const ASK_RULES = Object.freeze([
  { matchType: 'word', pattern: 'tee', reason: 'Writes to file and stdout' },
  { matchType: 'regex', pattern: '\\s>>?\\s|\\s>>?$|^>>?\\s|\\d>>?\\s', reason: 'Shell output redirection' },
]);

/**
 * Test one command segment against a rule, ignoring leading whitespace.
 * @param {{ matchType: string, pattern: string }} rule
 * @param {string} command
 * @returns {boolean}
 */
function matchRule(rule, command) {
  const trimmed = command.trimStart();
  switch (rule.matchType) {
    case 'prefix':
      return trimmed.startsWith(rule.pattern);
    case 'regex':
      return new RegExp(rule.pattern).test(trimmed);
    case 'word':
      return new RegExp('\\b' + rule.pattern + '\\b').test(trimmed);
    default:
      return false;
  }
}

/**
 * Split a command line into its top-level segments on `;`, `|`, `&&` and `||`.
 * Quoted text, `(...)`/`{...}` groups and command substitutions stay inside
 * their segment.
 * @param {string} command
 * @param {(body: string) => void} [onSubshell] - called, as the scan reaches
 *   it, with the trimmed, non-empty body of each top-level `$(...)` or
 *   backtick substitution
 * @returns {string[]} The trimmed, non-empty segments
 * @throws {Error} When a command substitution is never closed
 */
function splitCommands(command, onSubshell = () => {}) {
  const parts = [];
  let depth = 0;
  let current = '';
  let inSingle = false;
  let inDouble = false;
  let escaped = false;

  for (let i = 0; i < command.length; i++) {
    const ch = command[i];

    if (escaped) {
      current += ch;
      escaped = false;
      continue;
    }
    if (ch === '\\' && !inSingle) {
      current += ch;
      escaped = true;
      continue;
    }
    if (ch === "'" && !inDouble) { inSingle = !inSingle; current += ch; continue; }
    if (ch === '"' && !inSingle) { inDouble = !inDouble; current += ch; continue; }

    const subshell = inSingle ? null : readSubshellAt(command, i);
    if (subshell) {
      const body = subshell.content.trim();
      if (body) onSubshell(body);
      current += subshell.text;
      i = subshell.end;
      continue;
    }

    if (inSingle || inDouble) {
      current += ch;
      continue;
    }

    if (ch === '(' || ch === '{') { depth++; current += ch; continue; }
    if (ch === ')') {
      if (depth > 0) {
        depth--;
      }
      current += ch;
      continue;
    }
    if (ch === '}') { depth--; current += ch; continue; }

    if (depth === 0) {
      const isDoubled = (ch === '&' || ch === '|') && command[i + 1] === ch;
      if (ch === ';' || ch === '|' || isDoubled) {
        parts.push(current);
        current = '';
        if (isDoubled) i++;
        continue;
      }
    }
    current += ch;
  }
  if (current) parts.push(current);
  return parts.map((p) => p.trim()).filter(Boolean);
}

/**
 * Read the `$(...)` or backtick command substitution that opens at index `i`.
 * @param {string} command
 * @param {number} i
 * @returns {{ content: string, end: number, text: string } | null} The
 *   substitution's body, the index of its closing character, and the body
 *   re-wrapped in its delimiters; null when no substitution opens at `i`
 * @throws {Error} When the substitution is never closed
 */
function readSubshellAt(command, i) {
  if (command[i] === '$' && command[i + 1] === '(') {
    const parsed = readDollarSubshell(command, i + 2);
    return { ...parsed, text: '$(' + parsed.content + ')' };
  }
  if (command[i] === '`') {
    const parsed = readBacktickSubshell(command, i + 1);
    return { ...parsed, text: '`' + parsed.content + '`' };
  }
  return null;
}

function readBacktickSubshell(command, startIndex) {
  let content = '';

  for (let i = startIndex; i < command.length; i++) {
    const ch = command[i];
    if (ch === '\\') {
      const next = command[i + 1];
      if (next === '`') {
        content += '`';
        i++;
        continue;
      }
      content += ch;
      continue;
    }
    if (ch === '`') {
      return { content, end: i };
    }
    content += ch;
  }

  throw new Error('Unterminated backtick command substitution');
}

function readDollarSubshell(command, startIndex) {
  let content = '';
  let inSingle = false;
  let inDouble = false;
  let escaped = false;

  for (let i = startIndex; i < command.length; i++) {
    const ch = command[i];

    if (escaped) {
      content += ch;
      escaped = false;
      continue;
    }
    if (ch === '\\' && !inSingle) {
      if (command[i + 1] === '`') {
        content += '`';
        i++;
        continue;
      }
      content += ch;
      escaped = true;
      continue;
    }
    if (ch === "'" && !inDouble) {
      inSingle = !inSingle;
      content += ch;
      continue;
    }
    if (ch === '"' && !inSingle) {
      inDouble = !inDouble;
      content += ch;
      continue;
    }
    if (inSingle) {
      content += ch;
      continue;
    }
    const subshell = readSubshellAt(command, i);
    if (subshell) {
      content += subshell.text;
      i = subshell.end;
      continue;
    }
    if (ch === ')') {
      return { content, end: i };
    }

    content += ch;
  }

  throw new Error('Unterminated $(...) command substitution');
}

/**
 * Check a shell command line against the canonical rules. Every segment
 * (split on `;`, `|`, `&&`, `||`) and every `$(...)` or backtick subshell is
 * tested; the first deny rule that matches any part wins, then the first ask
 * rule.
 * @param {string} command
 * @returns {{ action: 'deny'|'ask', reason: string } | { action: 'allow' }}
 * @throws {Error} When a command substitution is never closed
 */
function checkCommand(command) {
  const topLevel = [];
  const segments = splitCommands(command, (body) => topLevel.push(body));
  // Every substitution body is split once, as the scan of its enclosing body
  // reaches it, so nested bodies are visited in pre-order. The top-level scan
  // finishes first, so its unterminated-substitution error takes precedence.
  const subshells = [];
  const subshellSegments = [];
  const visit = (body) => {
    const index = subshells.push(body) - 1;
    subshellSegments[index] = splitCommands(body, visit);
  };
  topLevel.forEach(visit);
  const allParts = [...new Set([...segments, ...subshells, ...subshellSegments.flat()])];

  for (const [rules, action] of [[DENY_RULES, 'deny'], [ASK_RULES, 'ask']]) {
    for (const part of allParts) {
      const rule = rules.find((candidate) => matchRule(candidate, part));
      if (rule) {
        return { action, reason: rule.reason };
      }
    }
  }
  return { action: 'allow' };
}

module.exports = { DENY_RULES, ASK_RULES, matchRule, checkCommand };
